OPTIONAL_AT = (("edge-functions", "SUPABASE_SECRET_KEY"),)

# Workers that read env.SUPABASE_SECRET_KEY on a live path. `phone` and
# `webhooks` are in this list because they *read* it, not because they have it
# — their binding is still the old name (ETH-dh2ss), so they must report
# MISSING here until that is fixed.
CF_WORKERS = ("data-api", "inbox", "internal-api", "phone", "webhooks")

COOLIFY_APPS = ("email-sync", "vector")

# Surfaces no automated collector can reach. Declared rather than omitted: an
# omitted surface reads as "no drift", a declared one reads as "unverified".
MANUAL_SURFACES = (
    ("hermes-vm", "SUPABASE_ACCESS_TOKEN", "plaintext in /home/hermes/.hermes/config.yaml (sudo)"),
    ("laptop-hermes", "SUPABASE_ACCESS_TOKEN", "plaintext in ~/.hermes/config.yaml"),
    (
        "github-actions",
        "SUPABASE_ACCESS_TOKEN",
        "raw GHA secret, outside BWS (.github/workflows/ci.yml)",
    ),
)


def _cloudflare_fetcher(account_id: str, token: str):
    return json_getter(
        f"https://api.cloudflare.com/client/v4/accounts/{account_id}",
        {"Authorization": f"Bearer {token}", "User-Agent": "monocloud-key-fingerprints"},
    )


def _coolify_fetcher(token: str, cf_id: str, cf_secret: str):
    return json_getter(
        "https://coolify.ec1c.com/api/v1",
        {
            "Authorization": f"Bearer {token}",
            "CF-Access-Client-Id": cf_id,
            "CF-Access-Client-Secret": cf_secret,
            "User-Agent": "Mozilla/5.0 monocloud-key-fingerprints",
        },
    )


def _supabase_fetcher(pat: str):
    return json_getter(
        f"https://api.supabase.com/v1/projects/{PROJECT_REF}",
        {"Authorization": f"Bearer {pat}", "User-Agent": "monocloud-key-fingerprints"},
    )


def collect_all(env: dict[str, str], remotes: list[str]) -> list[Fingerprint]:
    """Sweep every declared surface. Never raises — unreachable becomes ERROR."""
    fps: list[Fingerprint] = list(collect_bws(env, TRACKED))

    cf_token, cf_account = env.get("CLOUDFLARE_API_TOKEN"), env.get("CLOUDFLARE_ACCOUNT_ID")
    if cf_token and cf_account:
        fps += collect_cf_worker_secrets(
            _cloudflare_fetcher(cf_account, cf_token), CF_WORKERS, [REFERENCE_NAME]
        )
    else:
        fps.append(
            manual_surface("cf-workers", REFERENCE_NAME, "CLOUDFLARE_API_TOKEN/ACCOUNT_ID unset")
        )

    coolify_token = REDACTED
    cfa_id, cfa_secret = REDACTED, env.get("CF_ACCESS_CLIENT_SECRET")
    if coolify_token and cfa_id and cfa_secret:
        fps += collect_coolify(
            _coolify_fetcher(coolify_token, cfa_id, cfa_secret), TRACKED, app_filter=COOLIFY_APPS
        )
    else:
        fps.append(manual_surface("coolify", REFERENCE_NAME, "Coolify/CF-Access creds unset"))

    pat = env.get("SUPABASE_PAT")
    if pat:
        fps += collect_edge_secrets(_supabase_fetcher(pat), TRACKED)
    else:
        fps.append(manual_surface("edge-functions", REFERENCE_NAME, "SUPABASE_PAT unset"))

    for spec in remotes:
        fps += collect_remote_env(
            default_command_runner, RemoteTarget.parse(spec), [REFERENCE_NAME]
        )
    if not remotes:
        fps.append(
            manual_surface(
                "running-containers",
                REFERENCE_NAME,
                "Coolify envs are static copies (ETH-lsomi); pass --remote host:container",
            )
        )

    fps += [manual_surface(s, n, d) for s, n, d in MANUAL_SURFACES]
    return mark_optional_at(mark_optional(fps, OPTIONAL), OPTIONAL_AT)


def report_usage(env: dict[str, str], window_hours: int, surfaces_clean: bool) -> None:
    """Backward half: print per-key request counts and the revocation verdict."""
    pat = env.get("SUPABASE_PAT")
    if not pat:
        print("\nusage: skipped — SUPABASE_PAT unset (a sb_secret_ key returns 401 here)")
        return
    runner = management_sql_runner(PROJECT_REF, pat)
    iso_start, iso_end = iso_window(window_hours)

    # Prove the window applied before trusting any count from it. The endpoint
    # takes its range from the iso params, and a request that loses them
    # silently collapses to ~1 minute.
    window_verified, window_note = window_coverage_ok(
        runner(window_span_sql(), iso_start, iso_end), window_hours
    )
    print(f"\nlog window {iso_start} .. {iso_end} — {window_note}")

